// Import settings for everything in Assets/Audio (regenerated by Tools/AudioGen/generate_audio.py):
//   SFX       -> Decompress On Load, Vorbis q70, mono  (instant playback, tiny clips)
//   Ambience  -> Compressed In Memory, Vorbis q60, mono
//   Music     -> Streaming, Vorbis q70, stereo         (long tracks, low memory)
using UnityEditor;
using UnityEngine;

public class RewindAudioImporter : AssetPostprocessor
{
    public override uint GetVersion() => 1;

    void OnPreprocessAudio()
    {
        if (!assetPath.StartsWith("Assets/Audio/")) return;
        var importer = (AudioImporter)assetImporter;
        var s = importer.defaultSampleSettings;
        s.compressionFormat = AudioCompressionFormat.Vorbis;
        s.sampleRateSetting = AudioSampleRateSetting.PreserveSampleRate;

        if (assetPath.Contains("/SFX/"))
        {
            s.loadType = AudioClipLoadType.DecompressOnLoad;
            s.quality = 0.7f;
            importer.forceToMono = true;
        }
        else if (assetPath.Contains("/Ambience/"))
        {
            s.loadType = AudioClipLoadType.CompressedInMemory;
            s.quality = 0.6f;
            importer.forceToMono = true;
        }
        else if (assetPath.Contains("/Music/"))
        {
            s.loadType = AudioClipLoadType.Streaming;
            s.quality = 0.7f;
            importer.forceToMono = false;
        }
        else return;

        importer.loadInBackground = !assetPath.Contains("/SFX/");
        importer.defaultSampleSettings = s;
    }
}
